using GamePulse.Api.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
namespace GamePulse.Api.Controllers;
public sealed class NhlExceptionFilter:IExceptionFilter{public void OnException(ExceptionContext c){if(c.Exception is NhlDataException e){c.Result=new ObjectResult(new{message=e.Message}){StatusCode=e.Status};c.ExceptionHandled=true;}}}
[ApiController,Route("api/leagues/nhl"),TypeFilter(typeof(NhlExceptionFilter))]
public sealed class NhlController(NhlDataService service):ControllerBase
{
 static NhlEntity Entity(NhlEntity[] rows,string id)=>rows.SingleOrDefault(p=>p.Id==id||p.Id.Split(':')[^1]==id)??throw new NhlDataException(404,"NHL entity not found in this season.");
 static object Page<T>(IEnumerable<T> source,int page,int pageSize){if(page<1||page>1000000||pageSize<1||pageSize>100)throw new NhlDataException(400,"Use page >= 1 and pageSize 1–100.");var rows=source.ToArray();return new{items=rows.Skip((page-1)*pageSize).Take(pageSize).ToArray(),total=rows.Length,page,pageSize};}
 static IEnumerable<NhlGame> Games(NhlSeason d,string phase,string? team=null)=>d.Games.Where(g=>g.SeasonType==phase&&(team==null||g.HomeTeamId==team||g.AwayTeamId==team)).OrderByDescending(g=>g.Date).ThenByDescending(g=>g.Id);
 [HttpGet("seasons")]public IActionResult Seasons()=>Ok(service.Seasons().Select(y=>y.ToString()));
 [HttpGet("coverage")]public async Task<IActionResult> Coverage(int? season,CancellationToken ct){var d=await service.Get(season,ct);return Ok(new{coverage=d.Coverage,provenance=d.Provenance});}
 [HttpGet("teams")]public async Task<IActionResult> Teams(int? season,CancellationToken ct)=>Ok((await service.Get(season,ct)).Teams.OrderBy(t=>t.Name));
 [HttpGet("players")]
 public async Task<IActionResult> Players(int? season,string? search,string? teamId,string? group,string? seasonType,int page=1,int pageSize=40,CancellationToken ct=default){var d=await service.Get(season,ct);var team=string.IsNullOrEmpty(teamId)?null:Entity(d.Teams,teamId).Id;var rows=d.Players.Where(p=>(string.IsNullOrEmpty(search)||(p.Name??p.Id).Contains(search.Trim(),StringComparison.OrdinalIgnoreCase))&&(team==null||p.TeamIds.Contains(team)));if(!string.IsNullOrEmpty(seasonType)){NhlInsights.Phase(seasonType);var phaseGames=d.Games.Where(g=>g.SeasonType==seasonType).Select(g=>g.Id).ToHashSet();rows=rows.Where(p=>p.GameIds.Length==0||p.GameIds.Any(phaseGames.Contains));}if(!string.IsNullOrEmpty(group)){NhlInsights.Group(group);rows=rows.Where(p=>group=="goalie"?p.Position=="G":p.Position!="G");}return Ok(Page(rows.OrderBy(p=>p.Name).ThenBy(p=>p.Id),page,pageSize));}
 [HttpGet("games")]
 public async Task<IActionResult> Schedule(int? season,string seasonType="Regular Season",string? teamId=null,string? date=null,string? status=null,int page=1,int pageSize=40,CancellationToken ct=default){NhlInsights.Phase(seasonType);var d=await service.Get(season,ct);var team=string.IsNullOrEmpty(teamId)?null:Entity(d.Teams,teamId).Id;var rows=Games(d,seasonType,team);if(!string.IsNullOrEmpty(date)){if(!DateOnly.TryParseExact(date,"yyyy-MM-dd",out _))throw new NhlDataException(400,"Use date YYYY-MM-DD.");rows=rows.Where(g=>g.Date==date);}if(!string.IsNullOrEmpty(status)){if(status is not("completed" or "scheduled"))throw new NhlDataException(400,"Unknown status.");rows=rows.Where(g=>g.Completed==(status=="completed"));}return Ok(Page(rows,page,pageSize));}
 [HttpGet("games/{id}")]
 public async Task<IActionResult> Game(string id,int? season,CancellationToken ct){var d=await service.Get(season,ct);var g=d.Games.SingleOrDefault(g=>g.Id==id)??throw new NhlDataException(404,"NHL game not found.");return Ok(new{game=g,teams=d.Teams.Where(t=>t.Id==g.HomeTeamId||t.Id==g.AwayTeamId),teamStats=d.TeamStats.Where(s=>s.GameId==id),playerStats=d.PlayerStats.Where(s=>s.GameId==id),players=d.Players.Where(p=>p.GameIds.Contains(id)),scoring=d.Scoring.Where(e=>e.GetProperty("gameId").GetString()==id),method=NhlInsights.Method});}
 [HttpGet("standings")]
 public async Task<IActionResult> Standings(int? season,CancellationToken ct){var d=await service.Get(season,ct);return Ok(new{season=d.Season,method="Calculated modern regular-season records: two points per win, one for an OT/SO loss. Unknown results keep points unknown. Sorted by points, regulation wins, then wins; not official division/wild-card seeding or complete NHL tiebreakers.",teams=d.Teams.Select(t=>new{team=t,record=NhlInsights.Scores("Season",Games(d,"Regular Season",t.Id),t.Id,"Regular Season")}).OrderByDescending(r=>r.record.Points).ThenByDescending(r=>r.record.RegulationWins).ThenByDescending(r=>r.record.Wins).ThenBy(r=>r.team.Name)});}
 async Task<object> Profile(string id,int? season,string phase,string? teamId,CancellationToken ct){NhlInsights.Phase(phase);var d=await service.Get(season,ct);var player=Entity(d.Players,id);var team=string.IsNullOrEmpty(teamId)?null:Entity(d.Teams,teamId).Id;return new{season=d.Season,seasonType=phase,player,teamId=team,teams=d.Teams,skater=NhlInsights.Player(d,player.Id,phase,"skater",team),goalie=NhlInsights.Player(d,player.Id,phase,"goalie",team),contributions=player.TeamIds.Select(t=>new{teamId=t,skater=NhlInsights.Player(d,player.Id,phase,"skater",t),goalie=NhlInsights.Player(d,player.Id,phase,"goalie",t)}).ToArray(),coverage=d.Coverage,method=NhlInsights.Method};}
 [HttpGet("players/{id}")]public async Task<IActionResult> Player(string id,int? season,string seasonType="Regular Season",string? teamId=null,CancellationToken ct=default)=>Ok(await Profile(id,season,seasonType,teamId,ct));
 [HttpGet("players/{id}/games")]
 public async Task<IActionResult> Log(string id,int? season,string seasonType="Regular Season",string? teamId=null,int page=1,int pageSize=20,CancellationToken ct=default){NhlInsights.Phase(seasonType);var d=await service.Get(season,ct);var player=Entity(d.Players,id);var team=string.IsNullOrEmpty(teamId)?null:Entity(d.Teams,teamId).Id;var stats=d.PlayerStats.Where(r=>r.PlayerId==player.Id&&(team==null||r.TeamId==team)).ToArray();var ids=stats.Select(r=>r.GameId).ToHashSet();return Ok(Page(Games(d,seasonType).Where(g=>ids.Contains(g.Id)).Select(g=>new{game=g,statistics=stats.Where(r=>r.GameId==g.Id).ToArray()}),page,pageSize));}
 [HttpGet("teams/{id}")]
 public async Task<IActionResult> Team(string id,int? season,string seasonType="Regular Season",CancellationToken ct=default){NhlInsights.Phase(seasonType);var d=await service.Get(season,ct);return Ok(new{analytics=NhlInsights.TeamProfile(d,Entity(d.Teams,id),seasonType),coverage=d.Coverage,method=NhlInsights.Method});}
 [HttpGet("analytics")]
 public async Task<IActionResult> Analytics(int? season,string seasonType="Regular Season",CancellationToken ct=default){NhlInsights.Phase(seasonType);var d=await service.Get(season,ct);return Ok(new{season=d.Season,seasonType,teams=d.Teams.OrderBy(t=>t.Name).Select(t=>NhlInsights.TeamProfile(d,t,seasonType)),coverage=d.Coverage,method=NhlInsights.Method});}
 [HttpGet("statistics")]
 public async Task<IActionResult> Statistics(int? season,string group="skater",string kind="player",string seasonType="Regular Season",string? teamId=null,string? search=null,string? metric=null,int minGames=0,int minShots=0,int minMinutes=0,int page=1,int pageSize=40,CancellationToken ct=default){NhlInsights.Phase(seasonType);if(kind is not("player" or "team"))throw new NhlDataException(400,"Unknown statistics kind.");NhlInsights.Group(group);if(new[]{minGames,minShots,minMinutes}.Any(n=>n<0||n>1000000))throw new NhlDataException(400,"Minimums must be 0–1000000.");var d=await service.Get(season,ct);var team=string.IsNullOrEmpty(teamId)?null:Entity(d.Teams,teamId).Id;var ids=Games(d,seasonType).Select(g=>g.Id).ToHashSet();var rows=(kind=="team"?d.TeamStats:d.PlayerStats).Where(r=>ids.Contains(r.GameId)&&(kind=="team"||r.Group==group)&&(team==null||r.TeamId==team));var entities=kind=="team"?d.Teams:d.Players;var all=rows.GroupBy(r=>kind=="team"?r.TeamId:r.PlayerId!).Select(g=>NhlInsights.Aggregate(g.Key,entities.Single(p=>p.Id==g.Key).Name??g.Key,kind=="team"?"team":group,g)!).ToArray();var selected=metric??(kind=="team"?"goals":group=="goalie"?"saves":"points");var keys=kind=="team"?NhlInsights.Team:group=="goalie"?NhlInsights.Goalie:NhlInsights.Skater;var rates=kind=="team"?new[]{"goalsPerGame","shotsPerGame"}:group=="goalie"?new[]{"savePercentage","gaa"}:new[]{"goalsPerGame","shotsPerGame","pointsPerGame","shootingPercentage","toiPerGame"};if(!keys.Concat(rates).Contains(selected))throw new NhlDataException(400,"Unknown NHL metric.");double? Val(NhlInsights.Summary s)=>s.Rates.TryGetValue(selected,out var v)?v:s.Totals.GetValueOrDefault(selected);var eligible=all.Where(s=>s.Games>=minGames&&(minShots==0||s.Totals.GetValueOrDefault(group=="goalie"?"shotsAgainst":"shots")>=minShots)&&(minMinutes==0||s.Totals.GetValueOrDefault("toiSeconds")>=60L*minMinutes));var sorted=(selected=="gaa"?eligible.OrderBy(s=>Val(s)==null).ThenBy(Val):eligible.OrderBy(s=>Val(s)==null).ThenByDescending(Val)).ThenBy(s=>s.Name,StringComparer.Ordinal).ThenBy(s=>s.Id,StringComparer.Ordinal).ToArray();int? previousRank=null;double? previous=null;var ranked=sorted.Select((s,i)=>{var v=Val(s);int? rank=v.HasValue?(previous.HasValue&&v==previous?previousRank:i+1):null;previous=v;previousRank=rank;return new{rank,summary=s};}).Where(r=>string.IsNullOrWhiteSpace(search)||r.summary.Name.Contains(search.Trim(),StringComparison.OrdinalIgnoreCase));return Ok(new{season=d.Season,seasonType,group,kind,metric=selected,results=Page(ranked,page,pageSize),coverage=d.Coverage,method=NhlInsights.Method});}
 [HttpGet("compare")]
 public async Task<IActionResult> Compare(string leftId,string rightId,int leftSeason,int rightSeason,string group="skater",string seasonType="Regular Season",string? leftTeamId=null,string? rightTeamId=null,CancellationToken ct=default){NhlInsights.Group(group);return Ok(new{group,left=await Profile(leftId,leftSeason,seasonType,leftTeamId,ct),right=await Profile(rightId,rightSeason,seasonType,rightTeamId,ct),method=NhlInsights.Method});}
}
